// friday13.cs — Friday the 13th explorer (proleptic Gregorian calendar)

// Find the earliest Friday the 13th starting from 0001-01-01
DateOnly earliest = default;
for (int y = 1; y <= 400; y++)
{
    for (int m = 1; m <= 12; m++)
    {
        var d = new DateOnly(y, m, 13);
        if (d.DayOfWeek == DayOfWeek.Friday)
        {
            earliest ??= d;
            // don't break — we still need the count below
        }
    }
}

// Count Friday the 13ths in one full 400-year cycle (years 1–400)
// The Gregorian calendar repeats exactly every 400 years.
int count = 0;
DateOnly? first = null;
DateOnly? last = null;
for (int y = 1; y <= 400; y++)
{
    for (int m = 1; m <= 12; m++)
    {
        var d = new DateOnly(y, m, 13);
        if (d.DayOfWeek == DayOfWeek.Friday)
        {
            count++;
            first ??= d;
            last = d;
        }
    }
}

Console.WriteLine($"Earliest Friday the 13th:  {first:yyyy-MM-dd}");
Console.WriteLine($"Last in 400-year cycle:    {last:yyyy-MM-dd}");
Console.WriteLine($"Total Friday the 13ths in 400-year cycle: {count}");
Console.WriteLine($"Average per year: {count / 400.0:F4}");

// Bonus: distribution by month
Console.WriteLine();
Console.WriteLine("Distribution by month:");
var byMonth = new int[13];
for (int y = 1; y <= 400; y++)
    for (int m = 1; m <= 12; m++)
        if (new DateOnly(y, m, 13).DayOfWeek == DayOfWeek.Friday)
            byMonth[m]++;

for (int m = 1; m <= 12; m++)
    Console.WriteLine($"  {new DateOnly(2000, m, 1):MMMM,-12} {byMonth[m],3}");

